function instructionSections(f){const t=track(f.kind);return [
 {heading:'Correct route and court',paragraphs:[`This application uses section ${stat(f.kind)} only. Use the court identified in the application, confirmed from the original record.`,t.rules.filing,'Confirm that the court accepts this custom application and proposed order. Use any mandatory local form instead. Confirm whether the application uses the original case number or opens a new case. A new case number and judge assignment remain for the clerk.']},
 {heading:'Record checks before filing',paragraphs:t.participantFilingRequirements.map(r=>`${r.name}: ${r.howToObtain}`)},
 {heading:'Alcohol-related enforcement contacts - section 302.525.3',paragraphs:[ENFORCEMENT,'An administrative suspension or chemical-test refusal can matter even without a criminal conviction. Compare actual Missouri and out-of-state driver records. Stop for legal help if an entry is ambiguous; this packet does not decide the legal meaning of an individual entry.']},
 {heading:'Timing, first offense and once-in-a-lifetime choice',paragraphs:[f.kind==='mip'?'The earliest application is at age twenty-two: at least one year after the twenty-first birthday. The clock does not start at conviction. The conviction must be under Missouri section 311.325, not a local ordinance.':'Wait at least ten years from the plea or conviction. The required hearing tests subsequent convictions, subsequent alcohol-related enforcement contacts, and pending offenses or enforcement actions at the hearing. Do not substitute section 610.140.',`Section ${stat(f.kind)} permits one expungement under that section. The application states firstness and other qualifying facts only as the participant\'s own allegations; the court determines them. Relief is mandatory when the statutory findings are made.`,`Review every allegation and record before personally signing and dating. Ask the clerk whether local acknowledgment or notarization is required; no notarization is prescribed by this section.`]},
 {heading:'Official companions and protected blanks',paragraphs:['FI-05 is included only when a new circuit or associate circuit case is opened and the court requires it. Its Case Type Code and Case Type Description remain REQUIRED BEFORE FILING for clerk confirmation: the held case-types list does not name this specific statute. Do not borrow X5 or XG from a different route. The clerk supplies the Filing Date, Case number and Judge or Division. The full official trailing pages and submitter fields are retained.', 'GN10 is included only when the applicant requests a waiver, supplies actual financial facts and confirms the court accepts it. Review all income, spouse/dependent facts, expenses, property and debt entries, then personally sign Your Signature and Date. GN10 Respondent’s Address/Telephone requires clerk confirmation before filing when multiple agency respondents are listed. Do not fill the clerk’s Date File Stamp or court assignment fields.','Leave every proposed-order finding, grant/deny choice, court direction, order date and judicial signature for the court. Do not obtain a signed order as a prerequisite to filing.']},
 {heading:'Filing costs and waiver',paragraphs:[t.rules.fees,t.rules.feeWaiver,'Record retrieval costs are separate from filing costs. No fixed filing fee or waiver outcome is promised.']},
 {heading:'Hearing, notice and actual service',paragraphs:[t.rules.notice,t.rules.service,'Ask the clerk who gives any required notice, how, to whom, the copy count and whether any hearing is scheduled. The certificate is used only for court-directed actual service; supply its recipients, destinations, documents, method and dates only after service.']},
 {heading:'After a ruling',paragraphs:[`Obtain a copy of the entered ruling and ask the clerk about distribution to the identified record custodians, including the Department of Revenue where applicable. Section ${stat(f.kind)} controls the effect and confidentiality of the official records; do not assume a private database or a separate matter disappears. Officials may retain records needed to enforce the one-expungement limit.`]},
 {heading:'Stop and obtain individual legal help',paragraphs:t.selfHelpStopConditions},
 {heading:'Review fixture notice',paragraphs:['These sample facts are synthetic. Do not file this review packet. A build creates no commercial or participant-delivery authority.']}
 ];}
